function validSchoolMathDraft(id,v){
 if(!schoolMathWorksheets[id]||!v||v.type!=='school-math-v1'||!v.answers||typeof v.answers!=='object'||Array.isArray(v.answers)||!v.drawings||typeof v.drawings!=='object'||Array.isArray(v.drawings))return false;
 if(Object.keys(v.answers).length>500||Object.keys(v.drawings).length>40)return false;
 if(!Object.entries(v.answers).every(([k,x])=>/^[a-zA-Z0-9-]{1,80}$/.test(k)&&(typeof x==='boolean'||typeof x==='string'&&x.length<=2000)))return false;
 let points=0;for(const [k,strokes]of Object.entries(v.drawings)){if(!/^[a-zA-Z0-9-]{1,80}$/.test(k)||!Array.isArray(strokes)||strokes.length>80)return false;for(const stroke of strokes){if(!Array.isArray(stroke)||stroke.length>250)return false;points+=stroke.length;if(!stroke.every(p=>Array.isArray(p)&&p.length===2&&p.every(Number.isFinite)&&p[0]>=0&&p[0]<=500&&p[1]>=0&&p[1]<=260))return false;}}
 return points<=12000;
}
