function schoolMathPoint(pad,event){const p=pad.createSVGPoint();p.x=event.clientX;p.y=event.clientY;const local=p.matrixTransform(pad.getScreenCTM().inverse());return [Math.round(Math.max(0,Math.min(500,local.x))*10)/10,Math.round(Math.max(0,Math.min(260,local.y))*10)/10];}
document.addEventListener('pointerdown',event=>{const pad=event.target.closest('[data-math-pad]');if(!pad||event.button!==0)return;event.preventDefault();const panel=pad.closest('[data-math-worksheet]'),draft=readSchoolMathDraft(panel.dataset.mathWorksheet),points=[schoolMathPoint(pad,event)];activeSchoolMathStroke={pad,panel,draft,points,pointerId:event.pointerId};pad.setPointerCapture(event.pointerId);});
