function mathNormal(value){return String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[đĐ]/g,'d').replace(/[−–—]/g,'-').toLowerCase().trim().replace(/^(a|an|the)\s+/,'').replace(/[^a-z0-9+-]/g,'').replace(/(?<=[a-z])-(?=[a-z])/g,'');}
function mathNumeric(value){const s=String(value??'').trim().replace(/,/g,'').replace(/^\$/,'');const m=s.match(/^([-+]?\d+(?:\.\d+)?)\s*(?:[a-zA-Z$]+)?$/);return m?Number(m[1]):NaN;}
