function mathParseFact(value){
 let s=String(value??'').toLowerCase().replace(/multiplied by|times/g,'*').replace(/divided by/g,'/').replace(/[×x]/g,'*').replace(/[÷:]/g,'/').replace(/[−–]/g,'-').replace(/[,\s]/g,'').replace(/\$/g,'').replace(/(?<=\d)(?:metres?|meters?|cm|m|cents?|c|dollars?)(?=[=*\/+-]|$)/g,'').replace(/(?:metres?|meters?|cm|m|cents?|c|dollars?|\$)$/,'').replace(/\.$/,'');
 let m=s.match(/^(-?\d+(?:\.\d+)?)([*\/+\-])(-?\d+(?:\.\d+)?)=(-?\d+(?:\.\d+)?)$/);if(m)return {a:Number(m[1]),op:m[2],b:Number(m[3]),result:Number(m[4])};
 m=s.match(/^(-?\d+(?:\.\d+)?)=(-?\d+(?:\.\d+)?)([*\/+\-])(-?\d+(?:\.\d+)?)$/);return m?{a:Number(m[2]),op:m[3],b:Number(m[4]),result:Number(m[1])}:null;
}
function mathIsProduct(value,a,b){const f=mathParseFact(value);return !!f&&f.op==='*'&&f.result===a*b&&(f.a===a&&f.b===b||f.a===b&&f.b===a);}
function mathFactsIn(value){return (String(value??'').match(/\d+\s*[×x*÷/:+−-]\s*\d+\s*=\s*\d+|\d+\s*=\s*\d+\s*[×x*÷/:+−-]\s*\d+/g)||[]);}
function mathLength(value,expected,unit){const s=String(value??'').trim().toLowerCase(),m=s.match(/^([+]?[0-9]+(?:\.[0-9]+)?)\s*(cm|mm|m|centimetres?|centimeters?|metres?|meters?)?$/);if(!m)return false;const scales={cm:1,mm:0.1,m:100},u=m[2]?m[2].startsWith('cent')?'cm':m[2].startsWith('met')?'m':m[2]:unit;return Math.abs(Number(m[1])*scales[u]-expected*scales[unit])<1e-8;}
